"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import {
  Card,
  CardAction,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import { RadialGauge } from "@/registry/dashboardcn/ui/radial-gauge"
import { TickBar } from "@/registry/dashboardcn/ui/tick-bar"
import { MetricValue } from "@/registry/dashboardcn/ui/metric-value"

export interface ScoreGaugeItem {
  label: string
  /** Text after the label, e.g. "7h 50m" renders "Duration: 7h 50m". */
  detail?: string
  value: number
  max: number
  /** Any CSS color for the bar. Defaults to the card color. */
  color?: string
}

export interface ScoreGaugeStatus {
  /** Lowest score that earns this label. */
  min: number
  label: string
}

/** Applied to the score as a share of max when neither status nor statuses is given. */
const defaultStatuses: ScoreGaugeStatus[] = [
  { min: 0, label: "Poor" },
  { min: 50, label: "Fair" },
  { min: 70, label: "Good" },
  { min: 85, label: "Excellent" },
]

export interface ScoreGaugeCardProps extends React.ComponentProps<typeof Card> {
  title: string
  /** Headline word, e.g. "Excellent". Derived from statuses when omitted. */
  status?: string
  /** Score thresholds used to derive the headline word, e.g. [{ min: 85, label: "Excellent" }]. */
  statuses?: ScoreGaugeStatus[]
  /** Period text under the headline, e.g. "29 Jun - 5 Jul". */
  caption?: string
  score: number
  max?: number
  /** Any CSS color for the gauge and bars. Defaults to chart-1. */
  color?: string
  /** Gauge diameter in pixels. */
  gaugeSize?: number
  /** Gauge stroke width in pixels. */
  thickness?: number
  /** Number of gauge segments. 0 draws a continuous arc. */
  segments?: number
  /** Gap between gauge segments in degrees. */
  segmentGap?: number
  /** Gauge sweep in degrees. 360 draws a ring, 180 a semicircle. */
  sweep?: number
  /** Ticks in each breakdown bar. 0 draws a solid bar. */
  barSegments?: number
  /** Breakdown rows, each with a bar filled to value/max. */
  items: ScoreGaugeItem[]
  /** Slot in the top-right corner, e.g. a menu button. */
  action?: React.ReactNode
}

function deriveStatus(score: number, statuses: ScoreGaugeStatus[]) {
  let match: ScoreGaugeStatus | undefined
  for (const status of statuses) {
    if (score >= status.min && (!match || status.min >= match.min)) match = status
  }
  return match?.label
}

/** A score card with a headline word, a radial gauge around the score, and a breakdown list of labelled bars. */
function ScoreGaugeCard({
  title,
  status,
  statuses,
  caption,
  score,
  max = 100,
  color = "var(--chart-1)",
  gaugeSize = 160,
  thickness = 12,
  segments = 0,
  segmentGap = 2,
  sweep = 360,
  barSegments = 0,
  items,
  action,
  className,
  ...props
}: ScoreGaugeCardProps) {
  const headline =
    status ??
    (statuses
      ? deriveStatus(score, statuses)
      : deriveStatus((score / (max || 1)) * 100, defaultStatuses))

  return (
    <Card
      data-slot="score-gauge-card"
      className={cn("@container/card gap-4", className)}
      {...props}
    >
      <CardHeader>
        <CardDescription>{title}</CardDescription>
        {headline ? (
          <CardTitle className="text-2xl font-semibold tracking-tight">{headline}</CardTitle>
        ) : null}
        {caption ? (
          <div className="text-muted-foreground text-sm tabular-nums">{caption}</div>
        ) : null}
        {action ? <CardAction>{action}</CardAction> : null}
      </CardHeader>
      <CardContent>
        <div className="flex flex-col items-center gap-6 @sm/card:flex-row @sm/card:items-center @sm/card:gap-8">
          <RadialGauge
            value={score}
            max={max}
            size={gaugeSize}
            thickness={thickness}
            segments={segments}
            gap={segmentGap}
            sweep={sweep}
            color={color}
            aria-label={`${title}: ${score} of ${max}`}
            className="shrink-0"
          >
            <MetricValue
              value={score}
              className="text-4xl font-semibold tracking-tight"
            />
          </RadialGauge>
          <ul className="flex w-full min-w-0 flex-1 flex-col gap-4">
            {items.map((item) => {
              const fraction = Math.min(1, Math.max(0, item.value / (item.max || 1)))
              const barColor = item.color ?? color
              return (
                <li key={item.label} className="flex flex-col gap-1.5">
                  <div className="flex items-baseline justify-between gap-3 text-sm">
                    <span className="min-w-0 truncate">
                      <span className="font-medium">{item.label}</span>
                      {item.detail ? (
                        <span className="text-muted-foreground">: {item.detail}</span>
                      ) : null}
                    </span>
                    <span className="text-muted-foreground shrink-0 tabular-nums">
                      <MetricValue value={item.value} className="text-foreground font-medium" />
                      /
                      <MetricValue value={item.max} />
                    </span>
                  </div>
                  {barSegments > 0 ? (
                    <TickBar
                      value={item.value}
                      max={item.max}
                      segments={barSegments}
                      shape="pill"
                      color={barColor}
                      className="h-2"
                    />
                  ) : (
                    <div
                      role="progressbar"
                      aria-label={item.label}
                      aria-valuemin={0}
                      aria-valuemax={item.max}
                      aria-valuenow={item.value}
                      className="bg-muted h-2 w-full overflow-hidden rounded-full"
                    >
                      <div
                        className="h-full rounded-full transition-[width] duration-500"
                        style={{
                          width: `${Math.round(fraction * 1000) / 10}%`,
                          backgroundColor: barColor,
                        }}
                      />
                    </div>
                  )}
                </li>
              )
            })}
          </ul>
        </div>
      </CardContent>
    </Card>
  )
}

export { ScoreGaugeCard }

import * as React from "react"

import { cn } from "@/lib/utils"

export interface RadialGaugeProps extends React.ComponentProps<"div"> {
  value: number
  min?: number
  max?: number
  /** Diameter in pixels. */
  size?: number
  /** Stroke width in pixels. */
  thickness?: number
  /** Number of arc segments. 0 draws a continuous arc. */
  segments?: number
  /** Gap between segments in degrees. */
  gap?: number
  /** Angle where the arc starts, in degrees clockwise from 12 o'clock. */
  startAngle?: number
  /** Total sweep of the arc in degrees. 180 is a semicircle, 360 a ring. */
  sweep?: number
  /** Any CSS color. Defaults to chart-1. */
  color?: string
  trackColor?: string
  /** Content rendered in the middle of the gauge. */
  children?: React.ReactNode
}

// Round so server and client render identical path strings.
const round = (n: number) => Math.round(n * 1000) / 1000

function polar(cx: number, cy: number, r: number, angleDeg: number) {
  const rad = ((angleDeg - 90) * Math.PI) / 180
  return { x: round(cx + r * Math.cos(rad)), y: round(cy + r * Math.sin(rad)) }
}

function arcPath(cx: number, cy: number, r: number, from: number, to: number) {
  const start = polar(cx, cy, r, from)
  const end = polar(cx, cy, r, to)
  const largeArc = to - from > 180 ? 1 : 0
  return `M ${start.x} ${start.y} A ${r} ${r} 0 ${largeArc} 1 ${end.x} ${end.y}`
}

function RadialGauge({
  value,
  min = 0,
  max = 100,
  size = 160,
  thickness = 10,
  segments = 0,
  gap = 2,
  startAngle,
  sweep = 180,
  color = "var(--chart-1)",
  trackColor = "var(--muted)",
  className,
  children,
  ...props
}: RadialGaugeProps) {
  const fraction = Math.min(1, Math.max(0, (value - min) / (max - min || 1)))
  const start = startAngle ?? (sweep >= 360 ? 0 : -sweep / 2)
  const r = size / 2 - thickness / 2
  const cx = size / 2
  const cy = size / 2
  // Trim the box to the arc's vertical extent so a semicircle does not
  // reserve a full circle of space.
  const angles = Array.from({ length: 64 }, (_, i) => start + (sweep * i) / 63)
  const ys = angles.map((a) => polar(cx, cy, r, a).y)
  const top = Math.max(0, Math.min(...ys) - thickness / 2)
  const bottom = Math.min(size, Math.max(...ys) + thickness / 2)
  const height = bottom - top

  const arcs: { from: number; to: number; filled: boolean }[] = []
  if (segments > 0) {
    const step = sweep / segments
    for (let i = 0; i < segments; i++) {
      const from = start + i * step + gap / 2
      const to = start + (i + 1) * step - gap / 2
      const mid = (i + 0.5) / segments
      arcs.push({ from, to, filled: mid <= fraction })
    }
  }

  return (
    <div
      data-slot="radial-gauge"
      role="meter"
      aria-valuemin={min}
      aria-valuemax={max}
      aria-valuenow={value}
      className={cn("relative inline-flex shrink-0", className)}
      style={{ width: size, height }}
      {...props}
    >
      <svg
        width={size}
        height={height}
        viewBox={`0 ${top} ${size} ${height}`}
        className="absolute inset-0"
        aria-hidden="true"
      >
        {segments > 0 ? (
          arcs.map((arc, index) => (
            <path
              key={index}
              d={arcPath(cx, cy, r, arc.from, arc.to)}
              fill="none"
              stroke={arc.filled ? color : trackColor}
              strokeWidth={thickness}
              strokeLinecap="butt"
            />
          ))
        ) : (
          <>
            <path
              d={arcPath(cx, cy, r, start, start + sweep - (sweep >= 360 ? 0.01 : 0))}
              fill="none"
              stroke={trackColor}
              strokeWidth={thickness}
              strokeLinecap={sweep >= 360 ? "butt" : "round"}
            />
            {fraction > 0 ? (
              <path
                d={arcPath(cx, cy, r, start, start + sweep * fraction)}
                fill="none"
                stroke={color}
                strokeWidth={thickness}
                strokeLinecap="round"
                className="transition-[d] duration-500"
              />
            ) : null}
          </>
        )}
      </svg>
      {children ? (
        <div
          className={cn(
            "absolute inset-x-0 flex flex-col items-center justify-center text-center",
            sweep > 200 ? "inset-y-0" : "bottom-0"
          )}
        >
          {children}
        </div>
      ) : null}
    </div>
  )
}

export { RadialGauge }

import * as React from "react"

import { cn } from "@/lib/utils"

export interface TickBarProps extends React.ComponentProps<"div"> {
  /** Current value, from 0 to max. */
  value: number
  max?: number
  /** Number of ticks. */
  segments?: number
  /** Any CSS color for the filled ticks. Defaults to chart-1. */
  color?: string
  /** Any CSS color for the unfilled ticks. Defaults to muted. */
  trackColor?: string
  /** "tick" draws thin bars; "pill" draws wide rounded ones. */
  shape?: "tick" | "pill"
}

/** A progress bar drawn as a row of ticks, lit up to the current value. */
function TickBar({
  value,
  max = 100,
  segments = 40,
  color = "var(--chart-1)",
  trackColor,
  shape = "tick",
  className,
  ...props
}: TickBarProps) {
  const fraction = Math.min(1, Math.max(0, value / (max || 1)))
  // Any non-zero value lights at least one tick so small values still register.
  const filled = fraction === 0 ? 0 : Math.max(1, Math.round(fraction * segments))

  return (
    <div
      data-slot="tick-bar"
      data-shape={shape}
      role="progressbar"
      aria-valuemin={0}
      aria-valuemax={max}
      aria-valuenow={value}
      className={cn(
        "flex w-full",
        shape === "tick" ? "h-6 gap-[3px]" : "h-4 gap-1.5",
        className
      )}
      {...props}
    >
      {Array.from({ length: segments }, (_, index) => {
        const lit = index < filled
        return (
          <span
            key={index}
            data-filled={lit}
            className={cn(
              "bg-muted h-full min-w-0 flex-1 transition-colors",
              shape === "tick" ? "rounded-[1.5px]" : "rounded-full"
            )}
            style={{ backgroundColor: lit ? color : trackColor }}
          />
        )
      })}
    </div>
  )
}

export { TickBar }

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import { formatNumber, type NumberFormat } from "@/registry/dashboardcn/lib/format"
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip"

/** Values at or above this are abbreviated by default. */
export const DEFAULT_COMPACT_FROM = 100_000

export interface MetricValueProps extends Omit<React.ComponentProps<"span">, "children"> {
  /** Strings render as-is. */
  value: number | string
  format?: NumberFormat
  currency?: string
  maximumFractionDigits?: number
  /** Values at or above this are abbreviated (e.g. $158K) with the full value in a tooltip. Set to Infinity to always show the full value. */
  compactFrom?: number
  /** Text after the number, e.g. a unit. */
  suffix?: React.ReactNode
}

/** A formatted number. Large values are abbreviated and reveal the full value on hover. */
function MetricValue({
  value,
  format,
  currency,
  maximumFractionDigits,
  compactFrom = DEFAULT_COMPACT_FROM,
  suffix,
  className,
  ...props
}: MetricValueProps) {
  const classes = cn("tabular-nums", className)

  if (typeof value !== "number") {
    return (
      <span data-slot="metric-value" className={classes} {...props}>
        {value}
        {suffix}
      </span>
    )
  }

  const full = formatNumber(value, { format, currency, maximumFractionDigits })
  const abbreviate = format !== "percent" && Math.abs(value) >= compactFrom
  if (!abbreviate) {
    return (
      <span data-slot="metric-value" className={classes} {...props}>
        {full}
        {suffix}
      </span>
    )
  }

  return (
    <TooltipProvider>
      <Tooltip>
        <TooltipTrigger asChild>
          <span
            data-slot="metric-value"
            data-compact=""
            className={cn(classes, "cursor-default")}
            {...props}
          >
            {formatNumber(value, { format, currency, compact: true })}
            {suffix}
          </span>
        </TooltipTrigger>
        <TooltipContent className="tabular-nums">
          {full}
          {suffix}
        </TooltipContent>
      </Tooltip>
    </TooltipProvider>
  )
}

export { MetricValue }

export type NumberFormat = "number" | "compact" | "currency" | "percent"

export interface FormatNumberOptions {
  format?: NumberFormat
  /** ISO 4217 code, used when format is "currency". Defaults to USD. */
  currency?: string
  locale?: string
  maximumFractionDigits?: number
  /** Abbreviate large values, e.g. "$158K" instead of "$158,143". */
  compact?: boolean
}

const formatterCache = new Map<string, Intl.NumberFormat>()

function getFormatter(locale: string, options: Intl.NumberFormatOptions) {
  const key = locale + JSON.stringify(options)
  let formatter = formatterCache.get(key)
  if (!formatter) {
    formatter = new Intl.NumberFormat(locale, options)
    formatterCache.set(key, formatter)
  }
  return formatter
}

/**
 * Format a metric value for display.
 *
 * formatNumber(1234567)                          -> "1,234,567"
 * formatNumber(1234567, { format: "compact" })   -> "1.2M"
 * formatNumber(48.2, { format: "currency" })     -> "$48.20"
 * formatNumber(158143, { format: "currency", compact: true }) -> "$158K"
 * formatNumber(0.124, { format: "percent" })     -> "12.4%"
 */
export function formatNumber(
  value: number,
  {
    format = "number",
    currency = "USD",
    locale = "en-US",
    maximumFractionDigits,
    compact = false,
  }: FormatNumberOptions = {}
): string {
  if (!Number.isFinite(value)) return "—"

  // Compact values keep three significant digits: $158K, $1.23M, 41.2K.
  const compactOptions: Intl.NumberFormatOptions = compact
    ? maximumFractionDigits === undefined
      ? { notation: "compact", maximumSignificantDigits: 3 }
      : { notation: "compact", maximumFractionDigits }
    : {}
  switch (format) {
    case "compact":
      return getFormatter(locale, {
        notation: "compact",
        maximumFractionDigits: maximumFractionDigits ?? 1,
      }).format(value)
    case "currency":
      return getFormatter(locale, {
        style: "currency",
        currency,
        maximumFractionDigits: maximumFractionDigits ?? 2,
        ...compactOptions,
      }).format(value)
    case "percent":
      return getFormatter(locale, {
        style: "percent",
        maximumFractionDigits: maximumFractionDigits ?? 1,
      }).format(value)
    default:
      return getFormatter(locale, {
        maximumFractionDigits: maximumFractionDigits ?? 0,
        ...compactOptions,
      }).format(value)
  }
}

/**
 * Format a fractional change as a signed percentage.
 *
 * formatDelta(0.124)  -> "+12.4%"
 * formatDelta(-0.03)  -> "-3.0%"
 * formatDelta(0)      -> "0.0%"
 */
export function formatDelta(delta: number, locale = "en-US"): string {
  if (!Number.isFinite(delta)) return "—"
  return getFormatter(locale, {
    style: "percent",
    signDisplay: "exceptZero",
    maximumFractionDigits: 1,
    minimumFractionDigits: 1,
  }).format(delta)
}

/**
 * Fractional change between two values. Returns 0 when there is no baseline.
 */
export function computeDelta(current: number, previous: number): number {
  if (!previous) return 0
  return (current - previous) / Math.abs(previous)
}
